/**
 * @method
 * @name dts_listQuestion_OnLoadError
 * @description dts_listQuestion 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_listQuestion_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_listQuestion);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30319.dts_listQuestion_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_listQuestion_OnLoadCompleted
 * @description dts_listQuestion 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_listQuestion_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_listQuestion.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30319.dts_listQuestion_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.questNo = "input";
        const options = {
            id: "ULDSTF30322",
            title: "설문 등록",
            type: "browserPopup",
            width: "820px",
            height: "760px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/bizspt/ULDSTF30322.gfm", options);
        scwin.questNo = "";
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30319.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'QUEST_TITLE' && dts_listQuestion.getCellData(row, "QUEST_STAT_NM") === "진행예정") {
            const options = {
                id: "ULDSTF30322",
                title: "설문 관리",
                type: "browserPopup",
                width: "820px",
                height: "760px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/bizspt/ULDSTF30322.gfm", options);
            await scwin.listSync();
        } else if (colid === "QUEST_RESULT") {
            scwin.setQuestNo(row);
            await scwin.read(grd_Grid, row, colid);
            // frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30323.gfm", "결과보기" , 200, 10, 820, 720+30, "window" );

        } else if (colid === "QUEST_STAT_NM") {
            // 설문진행전 -> 설문진행중 .... 설문진행중 -> 설문종료,설문중지.... 설문중지 -> 설문진행중
            if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") === "진행예정" ||
                dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") === "진행" ||
                dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") === "중지") {
                const questNo = dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_NO");
                let questStat = "";
                if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") === "진행예정") {
                    if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STRT_DD") <= $c.ut.cGetToday("yyyymmdd")) {
                        questStat = "2";
                    }
                } else if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") === "진행") {
                    if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STRT_DD") <= $c.ut.cGetToday("yyyymmdd") &&
                        dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_END_DD") >= $c.ut.cGetToday("yyyymmdd")) {
                        questStat = "3";
                    } else if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") <= $c.ut.cGetToday("yyyymmdd") &&
                        dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_END_NM") <= $c.ut.cGetToday("yyyymmdd")) {
                        questStat = "1";
                    }
                } else if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") === "중지") {
                    if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STRT_DD") <= $c.ut.cGetToday("yyyymmdd") &&
                        dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_END_DD") >= $c.ut.cGetToday("yyyymmdd")) {
                        questStat = "2";
                    }
                }
                if (questStat === "2") {
                    let rtn = confirm('설문진행을 하시겠습니까?');
                    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

                    {
                        await scwin.statUpdate(scwin.questNo, questStat);
                        await scwin.listSync();
                    }
                } else if (questStat === "3") {
                    let rtn = confirm('설문진행을 중지하시겠습니까?');
                    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

                    {
                        await scwin.statUpdate(scwin.questNo, questStat);
                        await scwin.listSync();
                    }
                } else if (questStat === "1") {
                    let rtn = confirm('설문진행을 종료하시겠습니까?');
                    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

                    {
                        await scwin.statUpdate(scwin.questNo, questStat);
                        await scwin.listSync();
                    }
                }
            }
        } else if (colid === "QUEST_PREVIEW") {
            const id = dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_NO");
            if (id === "") return;
            let url = "/QuestionMgtPreview.do?method=previewQuest&id=" + id;
            await $c.frame.CreateDialogFrame("QUSET_PREVIEW", url, "미리보기", 200, 10, 700, 850, "window");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30319.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description rdo_MKT_ID onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // fn_SetCtrlByMktId();

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    const SDate = edt_SDate.getValue();
    const EDate = edt_EDate.getValue();
    const sbmOptions = {
        id : "sbm_dts_listQuestion",
        action : "/QuestionMgt.do",
        ref : "",
        target : "dts_listQuestion=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name statUpdate
 * @description ********************************************************************
