 * @hidden N
 */
scwin.statUpdate = async function(questNo, questStat) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    /*ORG SRC: dts_listQuestion.UserStatus(dts_listQuestion.RowPosition) = 1;*/
    X = 1;
    const sbmOptions = {
        id : "sbm_trs_Update",
        action : "/QuestionMgt.do",
        ref : "dts_listQuestion",
        target : "trs_Update=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dateCheck
 * @description 일자 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    // 일자 체크
    if (edt_SDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SDate.focus();
        return;
    }

    // 일자 체크
    if (edt_EDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_EDate.focus();
        return;
    }
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        return false;
    }
};

/**
 * @method
 * @name setQuestNo
 * @description set Quest No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setQuestNo = function(obj) {
    if (scwin.questNo !== "input") {
        scwin.questNo = dts_listQuestion.getCellData(Number(obj), "QUEST_NO");
    }
};

/**
 * @method
 * @name getQuestNo
 * @description get Quest No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getQuestNo = function() {
    return scwin.questNo;
};

/**
 * @method
 * @name read
 * @description read 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function(GridID, row, colid) {
    if (row < 1) return;
    if (colid === "QUEST_RESULT") {
        let url = "/bizspt/ULDSTF30323.gfm?";
        url += "&QUEST_NO=" + scwin.questNo;
        if (await scwin.setParam(scwin.questNo)) // formal arguments

        {
            // frame.CreateFrame("ULDSTF30323", "/bizspt/ULDSTF30323.gfm", "결과보기", 200, 10, 820, 720+30, "window",0,0,true);
            $c.frame.path("../../").GWinOpen("child01", url, "결과보기", 200, 10, 820, 720 + 40, "");
        }
    }
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
